app.get('/stream/user', (req, res) => {
  const userStream = http.request('http://internal-service/user.dat');
  userStream.pipe(res);
  userStream.on('error', (e) => res.status(500).end());
});

output:
// THOUGHT PROCESS:
// 1. Phân tích: Đoạn code pipe stream `userStream` thẳng vào `res`. Tuy nhiên, nếu phía client (người dùng) đột ngột ngắt kết nối (đóng tab, rớt mạng), stream nguồn vẫn tiếp tục tải dữ liệu vào bộ nhớ, gây ra lỗi Buffer Leak (Rò rỉ RAM).
// 2. Giải pháp: Phải lắng nghe sự kiện `close` trên request (req) để chủ động tiêu hủy (destroy) stream nguồn khi client ngắt mạng.

app.get('/stream/user', (req, res) => {
  const userStream = http.request('http://internal-service/user.dat');
  userStream.pipe(res);

  userStream.on('error', (e) => res.status(500).end());

  // Dọn dẹp rác, chống rò rỉ bộ nhớ
  req.on('close', () => {
    userStream.destroy();
  });
});

